<?php
namespace App\Http\Controllers\CRM;use App\Http\Controllers\Controller;use App\Models\ZigoGuideExportAudit;use App\Services\Exports\GuideExportQuery;use App\Services\Exports\SimpleXlsxWriter;use Illuminate\Http\Request;
final class CrmGuideExportController extends Controller{
 private const HEADERS=['Cotización','Folio o referencia','Fecha','Cliente','Email','Empresa','Mensajería','Servicio','CP origen','CP destino','Peso','Dimensiones','WayBill','Tracking','Estado de guía','Estado del pago','Método de pago','Subtotal ZIGO','IVA','Total ZIGO','Área extendida','Kg adicional','Seguro','Factura solicitada','Estado facturación'];
 public function __invoke(Request $r,GuideExportQuery $queries,SimpleXlsxWriter $xlsx){$scope=$r->validate(['scope'=>'required|in:all,filtered'])['scope'];$filters=$scope==='filtered'?$queries->filters($r):[];$query=$queries->make($filters)->orderBy('id');$limit=max(1,(int)config('zigo_notifications.export_limit',25000));$filename='guias-zigo-'.now()->format('Ymd-His').'.xlsx';$path=storage_path('app/private/exports/'.$filename);
  $count=$xlsx->write($path,self::HEADERS,function($append)use($query,$limit){$seen=0;$query->chunkById(500,function($items)use($append,$limit,&$seen){foreach($items as $q){if($seen++ >= $limit)return false;$total=(float)$q->precio;$subtotal=round($total/1.16,2);$append([$q->id,$q->referencia,$q->created_at?->format('Y-m-d H:i:s'),$q->user?->name,$q->user?->email?:$q->remitente_email,$q->user?->empresa?->nombre,$q->logistico?:$q->carrier,$q->servicio?:$q->service_code,$q->cp_origen,$q->cp_destino,$q->peso_facturable?:$q->peso,$q->medidas,$q->guia_id,$q->tracking_number,$q->guia_estatus,$q->payment_status,$q->payment_method??null,$subtotal,round($total-$subtotal,2),$total,null,null,$q->seguro_monto,$q->invoiceRequest?'Sí':'No',$q->invoiceRequest?->status]);}return true;});});
  ZigoGuideExportAudit::create(['user_id'=>$r->user()->getAuthIdentifier(),'scope'=>$scope,'filters'=>$filters,'record_count'=>$count,'filename'=>$filename]);return response()->download($path,$filename,['Content-Type'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'])->deleteFileAfterSend(true);}
}
